# Names that read better filled at text size (status marks); everything else defaults to outline.
_FILLED = {"check_circle", "cancel", "error", "warning", "help", "pending", "block", "do_not_disturb_on",
           "verified", "check_box", "notifications", "person", "lock", "schedule"}

# One meaning -> one symbol, used by site/build.py, site/scene.py and the pack pages.
STATUS = {
    "pass": "check_circle",     # green: proven, passed, caught
    "fail": "cancel",           # red: failed, wrong, got through
    "partial": "error",         # amber: weak evidence, held before, partial
    "warn": "warning",          # amber: needs care
    "unknown": "help",          # muted: refused, not checked
    "pending": "pending",       # amber: running / waiting
    "silent": "check_circle",   # tier: merges on its own
    "notify": "notifications",  # tier: merges, owner told
    "ask": "person",            # tier: a named human decides
    "block": "block",           # tier: cannot merge
}

# The old hand-made text glyphs, for callers that still produce them (e.g. pack_render._marks).
GLYPH = {"✓": "pass", "✔": "pass", "✗": "fail", "✕": "fail", "!": "warn", "◐": "partial",
         "?": "unknown", "…": "pending", "●": "pending", "–": "unknown"}


def icon(name: str, cls: str = "", label: str | None = None, fill: int | None = None) -> str:
    """Return an inline <svg> for a Material Symbol (or a STATUS meaning like "pass")."""
    name = STATUS.get(name, name)
    variants = _PATHS[name]
    f = (1 if name in _FILLED else 0) if fill is None else fill
    d = variants[min(f, len(variants) - 1)]
    klass = ("i " + cls).strip()
    a11y = f'role="img" aria-label="{escape(label)}"' if label else 'aria-hidden="true"'
    return (f'<svg class="{escape(klass)}" viewBox="0 -960 960 960" fill="currentColor" {a11y} '
            f'focusable="false"><path d="{d}"/></svg>')


# Base CSS every page that uses icon() should include.
CSS = (".i{width:1em;height:1em;flex:none;display:inline-block;vertical-align:-0.15em;fill:currentColor}"
       ".ic{display:inline-flex;align-items:center;gap:.4em}")
